package local.beatsync;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.media.projection.*;import android.widget.*;import android.Manifest;
public class MainActivity extends Activity {
 EditText address,room;TextView status;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(36,64,36,30);TextView title=new TextView(this);title.setText("BeatSync · Wi-Fi app audio");title.setTextSize(24);l.addView(title);address=new EditText(this);address.setSingleLine();address.setHint("Server URL printed by BeatSync");address.setText(getPreferences(0).getString("url",""));l.addView(address);room=new EditText(this);room.setSingleLine();room.setHint("Six-character room code");l.addView(room);Button start=new Button(this);start.setText("Start sharing app audio");l.addView(start);Button stop=new Button(this);stop.setText("Stop sharing");l.addView(stop);status=new TextView(this);status.setText("Same Wi-Fi required. Create a room on the Mac first. Approve audio/screen capture, then open your music app. Only app audio is sent; no screen video or microphone is streamed. Apps may block protected audio. Stop from this app or Android’s capture indicator.");l.addView(status);setContentView(l);start.setOnClickListener(v->{if(!room.getText().toString().trim().matches("[a-fA-F0-9]{6}")){status.setText("Enter the room’s six-character code.");return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},10);else capture();});stop.setOnClickListener(v->{stopService(new Intent(this,CastService.class));status.setText("Sharing stopped.");});}
 void capture(){try{String url=address.getText().toString().trim();java.net.URI u=new java.net.URI(url);if(!("http".equals(u.getScheme())||"https".equals(u.getScheme()))||u.getHost()==null)throw new Exception();getPreferences(0).edit().putString("url",url).apply();startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(),11);}catch(Exception e){status.setText("Enter a valid http:// or https:// server URL.");}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==10&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)capture();else status.setText("Android requires audio permission for playback capture. No microphone is captured.");}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==11&&result==RESULT_OK&&data!=null){Intent i=new Intent(this,CastService.class);i.putExtra("projection",data);i.putExtra("url",address.getText().toString().trim());i.putExtra("room",room.getText().toString().trim().toUpperCase());startForegroundService(i);status.setText("Capture is starting. Check the BeatSync notification for connection status, then open your music app.");}}
}
